1	// Tensor-core FlashAttention forward (sm_86): wmma m16n16k16 bf16, 8 warps,
2	// BLOCK_M=128 query rows, BLOCK_N=64 keys per tile, cp.async double-buffered
3	// K/V staging, tile-level (two-pass) softmax in the exp2 domain, GQA support.
4	// BF16 in/out, FP32 accumulation.
5	//
6	// Fragment layout note (verified for sm_86 m16n16k16): the C accumulator
7	// layout equals the matrix_a layout: lane l (gid=l/4, t=l%4) holds
8	//   x0=(gid,2t) x1=(gid,2t+1) x2=(gid+8,2t) x3=(gid+8,2t+1)
9	//   x4=(gid,2t+8) x5=(gid,2t+9) x6=(gid+8,2t+8) x7=(gid+8,2t+9)
10	// so the softmaxed S accumulator converts to the P matrix_a fragment in
11	// place (no shuffles). K tiles are consumed as matrix_b col_major (ldm 128),
12	// V tiles as matrix_b row_major (ldm 128).
13	
14	#include <torch/extension.h>
15	#include <ATen/cuda/CUDAContext.h>
16	#include <c10/cuda/CUDAGuard.h>
17	#include <cuda_bf16.h>
18	#include <mma.h>
19	#include <math.h>
20	#include <cstdint>
21	
22	namespace {
23	
24	constexpr int BLOCK_M = 128;  // query rows per block
25	constexpr int BLOCK_N = 64;   // key/value rows per tile
26	constexpr int HEAD_DIM = 128;
27	constexpr int NUM_WARPS = 8;
28	constexpr int NUM_THREADS = NUM_WARPS * 32;
29	constexpr int NBUFS = 2;                  // cp.async pipeline stages
30	constexpr int SMEM_BYTES = NBUFS * 2 * BLOCK_N * HEAD_DIM * 2;  // 64 KiB
31	constexpr float NEG_INF = -INFINITY;
32	
33	using namespace nvcuda;
34	
35	__device__ __forceinline__ float exp2_approx(float x) {
36	    float y;
37	    asm("ex2.approx.f32 %0, %1;" : "=f"(y) : "f"(x));
38	    return y;
39	}
40	
41	// 16-byte cp.async (Ampere).
42	__device__ __forceinline__ void cp_async16(void* smem, const void* gmem) {
43	    unsigned s = (unsigned)__cvta_generic_to_shared(smem);
44	    asm volatile("cp.async.cg.shared.global [%0], [%1], 16;" ::"r"(s), "l"(gmem));
45	}
46	
47	__device__ __forceinline__ void cp_async_commit() {
48	    asm volatile("cp.async.commit_group;");
49	}
50	
51	template <int N>
52	__device__ __forceinline__ void cp_async_wait() {
53	    asm volatile("cp.async.wait_group %0;" ::"n"(N));
54	}
55	
56	// Stage one K/V tile into buffer `buf` (zero-padding rows >= seq_len).
57	// sK/sV are raw pointers into dynamic shared memory (NBUFS*64*128 each).
58	__device__ __forceinline__ void stage_kv(
59	    __nv_bfloat16* __restrict__ sK, __nv_bfloat16* __restrict__ sV,
60	    const __nv_bfloat16* __restrict__ k,
61	    const __nv_bfloat16* __restrict__ v,
62	    long long base_kv, int seq_len, int nt, int buf)
63	{
64	    constexpr int NCHUNK = BLOCK_N * HEAD_DIM / 8;  // uint4 per matrix
65	    constexpr int TILE = BLOCK_N * HEAD_DIM;
66	    const uint4 zero = make_uint4(0, 0, 0, 0);
67	    for (int i = threadIdx.x; i < 2 * NCHUNK; i += NUM_THREADS) {
68	        const int mat = i / NCHUNK;          // 0 = K, 1 = V
69	        const int r = (i % NCHUNK) / 16;     // row within tile
70	        const int u = (i % NCHUNK) % 16;     // 16B chunk within row
71	        const int grow_kv = nt * BLOCK_N + r;
72	        __nv_bfloat16* dst = (mat == 0) ? &sK[buf * TILE + r * HEAD_DIM + u * 8]
73	                                        : &sV[buf * TILE + r * HEAD_DIM + u * 8];
74	        if (grow_kv < seq_len) {
75	            const __nv_bfloat16* src = (mat == 0) ? k : v;
76	            src += base_kv + (long long)grow_kv * HEAD_DIM + u * 8;
77	            cp_async16(dst, src);
78	        } else {
79	            *reinterpret_cast<uint4*>(dst) = zero;
80	        }
81	    }
82	}
